import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Scale, Menu, X } from 'lucide-react';
import './Header.css';

export default function Header() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const location = useLocation();

  const toggleMenu = () => setIsMenuOpen(!isMenuOpen);

  // Close mobile menu when route changes
  useEffect(() => {
    setIsMenuOpen(false);
  }, [location]);

  // Add scroll listener for header styling
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { path: '/', label: 'Home' },
    { path: '/about', label: 'About' },
    { path: '/services', label: 'Services' },
    { path: '/contact', label: 'Contact' }
  ];

  const isActive = (path) => location.pathname === path;

  return (
    <header className={`header ${isScrolled ? 'scrolled' : ''}`}>
      <div className="container header-content">
        {/* Logo */}
        <Link to="/" className="logo">
          <div className="logo-icon">
            <Scale size={28} />
          </div>
          <div className="logo-text">
            <span className="logo-primary">JUSTICE</span>
            <span className="logo-secondary">LAW CHAMBERS</span>
          </div>
        </Link>

        {/* Desktop Nav */}
        <nav className="desktop-nav">
          {navItems.map((item) => (
            <Link 
              key={item.path}
              to={item.path} 
              className={`nav-link ${isActive(item.path) ? 'active' : ''}`}
            >
              {item.label}
              {isActive(item.path) && <span className="active-indicator"></span>}
            </Link>
          ))}
          <Link to="/booking" className="btn btn-primary nav-cta">
            Book Appointment
          </Link>
        </nav>

        {/* Mobile Menu Button */}
        <button 
          className="mobile-toggle" 
          onClick={toggleMenu} 
          aria-label="Toggle menu"
          aria-expanded={isMenuOpen}
        >
          {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>

        {/* Mobile Nav Overlay */}
        <div className={`mobile-nav-overlay ${isMenuOpen ? 'open' : ''}`} onClick={toggleMenu}></div>

        {/* Mobile Nav */}
        <div className={`mobile-nav ${isMenuOpen ? 'open' : ''}`}>
          <div className="mobile-nav-header">
            <Link to="/" className="logo" onClick={toggleMenu}>
              <div className="logo-icon">
                <Scale size={24} />
              </div>
              <div className="logo-text">
                <span className="logo-primary">JUSTICE</span>
              </div>
            </Link>
            <button className="mobile-close" onClick={toggleMenu} aria-label="Close menu">
              <X size={24} />
            </button>
          </div>

          <nav className="mobile-nav-links">
            {navItems.map((item, index) => (
              <Link 
                key={item.path}
                to={item.path} 
                className={`mobile-nav-link ${isActive(item.path) ? 'active' : ''}`}
                style={{ animationDelay: `${index * 0.1}s` }}
              >
                {item.label}
              </Link>
            ))}
          </nav>

          <div className="mobile-nav-footer">
            <Link to="/booking" className="btn btn-primary btn-full" onClick={toggleMenu}>
              Book Appointment
            </Link>
            <div className="mobile-contact">
              <p>Need urgent help?</p>
              <a href="tel:+15551234567" className="mobile-phone">+1 (555) 123-4567</a>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
}

