import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { bookingService } from '../services/booking.service';
import { advocateService } from '../services/advocate.service';
import { Button, Input, Select, StatusMessage } from '../components/ui';
import { Calendar, Clock, User, Mail, Phone, FileText, ChevronRight, CheckCircle } from 'lucide-react';
import { useDocumentTitle } from '../hooks/useDocumentTitle';
import './Booking.css';

export default function Booking() {
    useDocumentTitle('Book Appointment');
    const navigate = useNavigate();
    const [currentStep, setCurrentStep] = useState(1);
    const [advocates, setAdvocates] = useState([]);
    const [availableSlots, setAvailableSlots] = useState([]);
    const [loading, setLoading] = useState(false);
    const [loadingAdvocates, setLoadingAdvocates] = useState(true);
    const [status, setStatus] = useState({ type: '', message: '' });

    const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: '',
        service: '',
        advocateId: '',
        date: '',
        time: '',
        notes: ''
    });

    const services = [
        'General Consultation',
        'Corporate Legal Advice',
        'Property Dispute Review',
        'Family Law Consultation',
        'Constitutional Law Consultation',
        'Consumer Litigation',
        'Contract Litigation',
        'Criminal Defense',
        'Immigration Law',
        'Intellectual Property'
    ];

    // Fetch advocates on mount
    useEffect(() => {
        const fetchAdvocates = async () => {
            try {
                const data = await advocateService.getAllAdvocates();
                setAdvocates(data);
            } catch (error) {
                console.error('Error fetching advocates:', error);
            } finally {
                setLoadingAdvocates(false);
            }
        };
        fetchAdvocates();
    }, []);

    // Fetch available slots when advocate and date are selected
    useEffect(() => {
        if (formData.advocateId && formData.date) {
            fetchAvailableSlots(formData.advocateId, formData.date);
        }
    }, [formData.advocateId, formData.date]);

    const fetchAvailableSlots = async (advocateId, date) => {
        try {
            const slots = await advocateService.getAvailableSlots(advocateId, date);
            setAvailableSlots(slots);
        } catch (error) {
            console.error('Error fetching slots:', error);
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
        setStatus({ type: '', message: '' });
    };

    const handleServiceSelect = (service) => {
        setFormData(prev => ({ ...prev, service }));
        setCurrentStep(2);
    };

    const handleAdvocateSelect = (advocateId) => {
        setFormData(prev => ({ ...prev, advocateId }));
        setCurrentStep(3);
    };

    const handleSlotSelect = (time) => {
        setFormData(prev => ({ ...prev, time }));
        setCurrentStep(4);
    };

    const validateStep = () => {
        switch (currentStep) {
            case 4:
                if (!formData.name || !formData.email || !formData.phone) {
                    setStatus({ type: 'error', message: 'Please fill in all required fields' });
                    return false;
                }
                if (!formData.email.includes('@')) {
                    setStatus({ type: 'error', message: 'Please enter a valid email address' });
                    return false;
                }
                break;
            default:
                return true;
        }
        return true;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!validateStep()) return;

        setLoading(true);
        setStatus({ type: '', message: '' });

        try {
            await bookingService.submitBooking(formData);
            // Navigate to confirmation page with booking data
            navigate('/booking-confirmation', { 
                state: { bookingData: formData },
                replace: true 
            });
        } catch (error) {
            console.error('Error submitting booking:', error);
            setStatus({ 
                type: 'error', 
                message: `Booking failed: ${error.message}. Please try again.` 
            });
        } finally {
            setLoading(false);
        }
    };

    const getSelectedAdvocate = () => {
        return advocates.find(a => a.id === formData.advocateId);
    };

    // Step indicators
    const steps = [
        { number: 1, label: 'Service', icon: FileText },
        { number: 2, label: 'Advocate', icon: User },
        { number: 3, label: 'Schedule', icon: Calendar },
        { number: 4, label: 'Details', icon: CheckCircle }
    ];

    return (
        <div className="booking-page">
            {/* Header */}
            <div className="booking-hero">
                <div className="container">
                    <h1 className="gradient-text">Book Your Consultation</h1>
                    <p>Connect with expert legal professionals in just a few steps</p>
                </div>
            </div>

            {/* Progress Steps */}
            <div className="booking-steps">
                <div className="container">
                    <div className="steps-wrapper">
                        {steps.map((step, index) => (
                            <React.Fragment key={step.number}>
                                <div className={`step ${currentStep >= step.number ? 'active' : ''} ${currentStep > step.number ? 'completed' : ''}`}>
                                    <div className="step-icon">
                                        <step.icon size={20} />
                                    </div>
                                    <span className="step-label">{step.label}</span>
                                </div>
                                {index < steps.length - 1 && (
                                    <div className={`step-connector ${currentStep > step.number ? 'completed' : ''}`}>
                                        <ChevronRight size={16} />
                                    </div>
                                )}
                            </React.Fragment>
                        ))}
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="container">
                <div className="booking-content">
                    <StatusMessage type={status.type} message={status.message} />

                    {/* Step 1: Select Service */}
                    {currentStep === 1 && (
                        <div className="step-content">
                            <h2>Select a Service</h2>
                            <p className="step-description">Choose the legal service you need assistance with</p>
                            <div className="services-grid">
                                {services.map((service) => (
                                    <div
                                        key={service}
                                        className={`service-card ${formData.service === service ? 'selected' : ''}`}
                                        onClick={() => handleServiceSelect(service)}
                                    >
                                        <FileText size={32} className="service-icon" />
                                        <span className="service-name">{service}</span>
                                        {formData.service === service && (
                                            <div className="selected-indicator">
                                                <CheckCircle size={20} />
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Step 2: Select Advocate */}
                    {currentStep === 2 && (
                        <div className="step-content">
                            <h2>Choose Your Advocate</h2>
                            <p className="step-description">Select a legal expert for your {formData.service}</p>

                            {loadingAdvocates ? (
                                <div className="loading-advocates">
                                    <div className="spinner"></div>
                                    <span>Loading advocates...</span>
                                </div>
                            ) : (
                                <div className="advocates-grid">
                                    {advocates.map((advocate) => (
                                        <div
                                            key={advocate.id}
                                            className={`advocate-card ${formData.advocateId === advocate.id ? 'selected' : ''}`}
                                            onClick={() => handleAdvocateSelect(advocate.id)}
                                        >
                                            <div className="advocate-avatar">
                                                {advocate.name.charAt(0)}
                                            </div>
                                            <div className="advocate-info">
                                                <h4>{advocate.name}</h4>
                                                <p className="advocate-specialty">{advocate.specialization}</p>
                                                <p className="advocate-experience">{advocate.experience} years experience</p>
                                                <div className="advocate-rating">
                                                    <span className="stars">{'★'.repeat(Math.floor(advocate.rating || 0))}</span>
                                                    <span className="rating-number">({advocate.rating || 0})</span>
                                                </div>
                                            </div>
                                            {formData.advocateId === advocate.id && (
                                                <div className="selected-indicator">
                                                    <CheckCircle size={20} />
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            )}

                            <button 
                                className="back-button"
                                onClick={() => setCurrentStep(1)}
                            >
                                ← Back to Services
                            </button>
                        </div>
                    )}

                    {/* Step 3: Select Date & Time */}
