    transition: all 0.4s ease;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

.cta-main-btn:hover {
    background: #ffd700;
    color: #1a1a2e;
    transform: translateY(-3px);
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
}

/* Responsive Design */
@media (max-width: 1024px) {
    .hero-stats {
        gap: var(--spacing-lg);
    }

    .stat-number {
        font-size: 2.25rem;
    }

    .action-btn {
        min-width: 260px;
    }
}

@media (max-width: 768px) {
    .hero-section {
        min-height: auto;
        padding: var(--header-height) 0 var(--spacing-xl);
    }

    .hero-content {
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .title-line {
        font-size: 2.25rem;
    }

    .hero-subtitle {
        font-size: 1rem;
    }

    .hero-actions {
        flex-direction: column;
        align-items: center;
    }

    .action-btn {
        width: 100%;
        max-width: 320px;
        min-width: auto;
    }

    .quick-contact-bar {
        flex-direction: column;
        gap: 12px;
        border-radius: 16px;
    }

    .contact-divider {
        display: none;
    }

    .hero-stats {
        flex-wrap: wrap;
        gap: var(--spacing-md);
        padding-top: var(--spacing-lg);
    }

    .stat-item {
        flex: 1;
        min-width: 120px;
    }

    .stat-number {
        font-size: 1.75rem;
    }

    .features-grid {
        grid-template-columns: 1fr;
    }

    .services-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    .title-line {
        font-size: 1.75rem;
    }

    .hero-badge {
        font-size: 0.8rem;
        padding: 8px 16px;
    }

    .action-btn {
        padding: 16px 20px;
    }

    .btn-icon-wrapper {
        width: 48px;
        height: 48px;
    }

    .btn-label {
        font-size: 1.1rem;
    }

    .feature-card {
        padding: var(--spacing-lg);
    }

    .feature-icon {
        width: 70px;
        height: 70px;
    }

    .stat-number {
        font-size: 1.5rem;
    }

    .stat-label {
        font-size: 0.75rem;
    }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
    .hero-section {
        background-attachment: scroll;
    }

    .feature-card,
    .service-item,
    .action-btn {
        transition: none;
    }
}

/* Print styles */
@media print {
    .hero-section {
        min-height: auto;
        background: white;
        color: black;
    }

    .hero-overlay,
    .cta-section::before,
    .cta-section::after {
        display: none;
    }

    .hero-title {
        color: black;
        text-shadow: none;
    }

    .feature-card {
        break-inside: avoid;
        border: 1px solid #ccc;
    }
}

